mapper.sql:
deleted = 0
and paid_time is not null
and paid_time >= #{startTime}
and paid_time < #{endTime}
and pay_status in (1, 3, 4, 5)
and ifnull(pay_channel, 1) in (1, 2)

    and store_id = #{storeId}

mapper.select:
select ifnull(sum(amount), 0)
from store_member_recharge
where deleted = 0
  and pay_status = 1
  and paid_time is not null
  and paid_time >= #{startTime}
  and paid_time < #{endTime}

    and store_id = #{storeId}

select count(distinct uid) from (
    select user_id as uid
    from mall_order
    where deleted = 0
      and user_id is not null
      and paid_time is not null
      and paid_time >= #{startTime}
      and paid_time < #{endTime}
      and pay_status in (1, 3, 4, 5)

      and store_id = #{storeId}

    union
    select customer_user_id as uid
    from store_verify_log
    where customer_user_id is not null
      and created_time >= #{startTime}
      and created_time < #{endTime}

      and store_id = #{storeId}

    union
    select user_id as uid
    from store_member_recharge
    where deleted = 0
      and pay_status = 1
      and user_id is not null
      and paid_time is not null
      and paid_time >= #{startTime}
      and paid_time < #{endTime}

      and store_id = #{storeId}

) t

select count(distinct user_id)
from store_member
where deleted = 0
  and user_id is not null
  and created_time >= #{startTime}
  and created_time < #{endTime}

  and store_id = #{storeId}

select day, count(distinct uid) as customers
from (
    select date_format(paid_time, '%Y-%m-%d') as day, user_id as uid
    from mall_order
    where deleted = 0
      and user_id is not null
      and paid_time is not null
      and paid_time >= #{startTime}
      and paid_time < #{endTime}
      and pay_status in (1, 3, 4, 5)

      and store_id = #{storeId}

    union
    select date_format(created_time, '%Y-%m-%d') as day, customer_user_id as uid
    from store_verify_log
    where customer_user_id is not null
      and created_time >= #{startTime}
      and created_time < #{endTime}

      and store_id = #{storeId}

    union
    select date_format(paid_time, '%Y-%m-%d') as day, user_id as uid
    from store_member_recharge
    where deleted = 0
      and pay_status = 1
      and user_id is not null
      and paid_time is not null
      and paid_time >= #{startTime}
      and paid_time < #{endTime}

      and store_id = #{storeId}

) t
group by day
order by day

select date_format(created_time, '%Y-%m-%d') as day,
       count(distinct user_id) as newCustomers
from store_member
where deleted = 0
  and user_id is not null
  and created_time >= #{startTime}
  and created_time < #{endTime}

  and store_id = #{storeId}

group by date_format(created_time, '%Y-%m-%d')
order by day
